    Set tArr = []

	Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT * FROM IHC_ITF_TPManage.TradingPartner order by Name")
	While rs.%Next() {
		if (rs.%Get("Name") '= "")
		{
			Do tArr.%Push({
				"Operation":"TPs",
				"id" : (rs.%Get("ID")),
				"Name":  (rs.%Get("Name")),
				"TPtype":    (rs.%Get("Type")),
				"ContactName":    			(rs.%Get("ContactName")),				
				"ContactPhone": 			(rs.%Get("ContactPhone")),
				"ContactEmail":        	(rs.%Get("ContactEmail"))				
			})
		}
	}
	Do ..%SetStatusCode(200)

	return tArr


