	}
} 

If '$IsObject(tp) {
	Set obj = {
		"ID": (id),
		"Error": 	"TP not found"
	}
} Else {

	Set obj = {
		"Operation":"GetTp",
		"id": (tp.%Id()),
		"Name": 		(tp.Name),
		"ContactName":        (tp.ContactName),
		"ContactPhone":   		(tp.ContactPhone),
		"ContactEmail":      (tp.ContactEmail),
		"TPtype":        (tp.Type)
	}


}
return obj

