			QUIT result
		}

	}
	else
	{
		Set tpLink = ##class(IHC.ITF.TPManage.TRADELINKS).%OpenId(obj.ID)
	}
	If $IsObject(tpLink) {

			set st = ..UpdateToTpLinkFromJSON(.tpLink,obj)

			IF ( st '= $$$OK)
			{
				// Set %response.Status = 400 // ..#HTTP400BADREQUEST
				Set error = {"errormessage": ("All fields not found: " _ st)}
				Write error.%ToJSON()
				Quit error
			}
			Set sc = tpLink.%Save()

			do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			if ($$$ISOK(sc)) {
				do result.%Set("ID", tpLink.%Id())
			}
			do result.%Set("Operation","UpdateTpLink")
			do result.%Set("LastmodDtTM",   (tpLink.LastmodDtTM))
			do result.%Set("Ack",  (tpLink.Ack))
			do result.%Set("Routing",  (tpLink.Routing))
			do result.%Set("SNIP",  (tpLink.SNIP))
			do result.%Set("Separators",  (tpLink.Separators))
			do result.%Set("UniqueId", (tpLink.UniqueId))
			do result.%Set("Active", (tpLink.Active))
			do result.%Set("Link", (tpLink.NAME))

	}
	else
	{
		set ^webService("UpdateTpLink Link") = "UpdateTpLink: Error ID or NAME required"
		do result.%Set("Error", "ID or NAME required for TRADELINKS Update")
	}

	Quit result

 	Do ..%SetStatusCode(200)
	#dim tpLink As IHC.ITF.TPManage.TRADELINKS	
	Set tpLink = ##class(IHC.ITF.TPManage.TRADELINKS).%OpenId(id)
	If '$IsObject(tpLink) {

		&SQL(select ID into :tpLinkId FROM IHC_ITF_TPManage.TRADELINKS where NAME = :id)
		if SQLCODE = 0
		{			
			Set tpLink = ##class(IHC.ITF.TPManage.TRADELINKS).%OpenId(tpLinkId)
		}
	}
	set cusArr = [] 
	If $IsObject(tpLink) { 

		if (tpLink.customProp.Size > 0)
		    {
		    	Set tKey=tpLink.customProp.Next("")
				while tKey'="" {

					#; Get the BindingTemplate object
					Set customP=tpLink.customProp.GetAt(tKey)

					#; Display it
					Do cusArr.%Push(
					{
						"Key":    (customP.Key),
						"Value": (customP.Value)
					})

					Set tKey=tpLink.customProp.Next(tKey)
				}
		    }

		Set obj = {
				"Link": (id),
				"TransType":(tpLink.TRANSTYPE.NAME),
				"TransactionSetId": (tpLink.TRANSTYPE.TransactionSetId),			
			"Operation":"GetTpLink",
			"ID": (tpLink.%Id()),
			"Name": 		(tpLink.NAME),
			"Mode":        (tpLink.Mode),
			"LastmodDtTM":   (tpLink.LastmodDtTM),
			// "TRANSTYPE":     (tpLink.TRANSTYPE.NAME),
			"IsaSenderId":   (tpLink.IsaSenderId.TPID),
			"IsaReceiverId": (tpLink.IsaReceiverId.TPID),
			"GsSenderId":    (tpLink.GsSenderId.TPID),
			"GsReceiverId":  (tpLink.GsReceiverId.TPID),
			"Mode":  (tpLink.Mode),
			"Ack":  (tpLink.Ack),
			"Routing":  (tpLink.Routing),
			"SNIP":  (tpLink.SNIP),
			"Separators":  (tpLink.Separators),
			"UniqueId": (tpLink.UniqueId),
			"Active": (tpLink.Active),
			"CustomProp": (cusArr)
		}
		Do ..%SetStatusCode(200)
		return obj

	}
	else
	{
		Set %response.Status = 200
		Set error = {"Error": ("TPLink ID not found: " _ id _ ", " _ tpLinkId)}
		Quit error
	}

	Do ..%SetStatusCode(200)
	set ^webService("DelTpLink") = "DelTpLink"

	 Set result={}
   	If '..GetJSONFromRequest(.obj) {
		// Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit error
	}
	set ^webService("DelTpLink") = "DelTpLink " _ obj.id
	#dim tpLink As IHC.ITF.TPManage.TRADELINKS	
	Set tpLink = ##class(IHC.ITF.TPManage.TRADELINKS).%OpenId(obj.id)
	If '$IsObject(tpLink) {
		set nm = obj.id
		&SQL(select ID into :tpLinkId FROM IHC_ITF_TPManage.TRADELINKS where NAME = :nm)
		if SQLCODE = 0
		{			
			Set tpLink = ##class(IHC.ITF.TPManage.TRADELINKS).%OpenId(tpLinkId)
		}
	} 
	If $IsObject(tpLink) {
		set tpLink.Active = 0
		set tpLink.LastmodDtTM = $ZDATETIME($HOROLOG,3, 1)
		set tpLink.LastmodID = obj.User

		Set sc = tpLink.%Save()

		set ^webService("DelTpLink") = "DelTpLink " _ obj.id _ ", stat: " _ sc
		do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))

		Set %response.Status = 200
		do result.%Set("Update", ("TPLink ID deactivated: " _ obj.id ))
	}
	else
	{
		Set result = {"Error": ("TPLink ID not found: " _ obj.id )}
	}
	Quit result

	set implArr = []

	&sql(DECLARE WPCursor CURSOR FOR SELECT tt.NAME, lnk.NAME, TransactionSetId, Direction, TRANSTYPE, Mode, Ack, GsReceiverId, 
		GsSenderId, IsaReceiverId, IsaSenderId, Routing, SNIP, Separators, Active 
		INTO :trans, :lnkNm, :transactionSetId, :direction, :type,:mode, :ack,  
		:gsReceiverId, :gsSenderId, :isaReceiverId, :isaSenderId, 
		:routing, :SNIP, :separators, :active
		from IHC_ITF_TPManage.TRADELINKS lnk, IHC_ITF_TPManage.TPIDS tpid, 
		IHC_ITF_TPManage.TRANSACTIONTYPES tt
		where (tpid.ID = lnk.IsaSenderId 
		OR		tpid.ID = lnk.IsaReceiverId 
		OR		tpid.ID = lnk.GsSenderId 
		OR		tpid.ID = lnk.IsaReceiverId) 

		AND TPID = :TPID AND tt.ID = lnk.TRANSTYPE order by lnk.NAME)
	&sql(OPEN WPCursor)
        if (SQLCODE'=0) {
	         Do implArr.%Push(
				{
					"TPID":    (TPID),
					"Error": (SQLCODE)
				})
				QUIT implArr
        }
   FOR { 
   		&sql(FETCH WPCursor)
        if (SQLCODE = 0) {

		Set tpId = ##class(IHC.ITF.TPManage.TPIDS).%OpenId(gsReceiverId)
		If $IsObject(tpId) {

			set gsReceiverTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ITF.TPManage.TPIDS).%OpenId(gsSenderId)
		If $IsObject(tpId) {

			set gsSenderTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ITF.TPManage.TPIDS).%OpenId(isaReceiverId)
		If $IsObject(tpId) {

			set isaReceiverTPIP = tpId.TPID
		}
