    while iter.%GetNext(.key , .value ) {
      try {

      	Set rs = ##class(%SQL.Statement).%ExecDirect(,"select ID, NAME, Direction FROM IHC_ITF_TPManage.TRANSACTIONTYPES where TransactionSetId = ?", value)
		While rs.%Next() {

			Set cm = ##class(IHC.ITF.TPManage.TRADELINKS).%New()
			set cm.NAME = obj.Link _ "-" _ obj.ParentTpId _ "-" _ rs.%Get("NAME") _ "-" _ mode  _ "-" _ rs.%Get("Direction")

			set cm.Mode = mode

			if ($L(obj.Separators) = 4)
			{
				set cm.Separators = obj.Separators
			}

			set cm.CreatedDtTM = dtTm
			set cm.LastmodDtTM = dtTm
			set cm.LastmodID = obj.User
			set cm.CreateID = obj.User

			if (mode = "Batch")
			{
				set cm.SNIP = $NUMBER(obj.BatchSNIP)
				set cm.Routing = obj.BatchRouting
				set cm.Ack = obj.BatchAck
			}
			else
			{
				set cm.SNIP = $NUMBER(obj.RtSNIP)
				set cm.Routing = "RT"
				set cm.Ack = obj.RtAck
			}

			set tranTypeId = rs.%Get("ID")

			if ( tranTypeId'= "")
			{
				#dim tt As IHC.ITF.TPManage.TRANSACTIONTYPES
				set tt = ##class(IHC.ITF.TPManage.TRANSACTIONTYPES).%OpenId(tranTypeId)
				set cm.TRANSTYPE = tt

			}

			if (rs.%Get("Direction") = "Inbound")
			{
					set cm.IsaReceiverId = payerTpIdObj
					set cm.IsaSenderId = provTpIdObj
					set cm.GsReceiverId = payerTpIdObj
					set cm.GsSenderId = provTpIdObj
			}
			else
			{
					set cm.IsaReceiverId = provTpIdObj
					set cm.IsaSenderId = payerTpIdObj
					set cm.GsReceiverId = provTpIdObj
					set cm.GsSenderId = payerTpIdObj 
			}

			Set sc = cm.%Save()

			if ($$$ISOK(sc))
			{
				do result.%Set(cm.NAME _ " Id", cm.%Id())
				do result.%Set("Status","OK")
			}
			else
			{
				do result.%Set(cm.NAME _ " Save",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			}

    	}
      } catch error{
	      do result.%Set("Err BulkTpLinks-ID " _ key ,error)
      }

	}

